from collections import OrderedDict

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if not inspect.isfunction(func):
            raise ValueError('The @ttl_cache decorator must be applied innermost of all decorators.')

        cache = OrderedDict()
        cache_size = 0

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            if key in cache:
                item = cache[key]
                if item['ttl'] > 0:
                    item['ttl'] -= ttl
                    if item['ttl'] <= 0:
                        del cache[key]
                        cache_size -= 1
                return item['value']
            result = func(*args, **kwargs)
            if cache_size < maxsize:
                cache[key] = {'ttl': ttl, 'value': result}
                cache_size += 1
            else:
                # Remove the least recently used item
                least_recent = min(cache, key=lambda k: cache[k]['ttl'])
                del cache[least_recent]
                cache[key] = {'ttl': ttl, 'value': result}
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            yield functools.partial(cache.__setitem__, key)
        memoize.put = put

        def forget(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            if key in cache:
                del cache[key]
                cache_size -= 1
        memoize.forget = forget

        def clear():
            cache.clear()
            cache_size = 0
        memoize.clear = clear

        return memoize

    return decorator

