from functools import wraps, partial

from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")

        cache = OrderedDict()
        cache_hits = 0
        cache_misses = 0

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            if key in cache:
                cache_hits += 1
                return cache[key]
            cache_misses += 1
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        @property
        def cache_stats(self):
            return {
                'hits': cache_hits,
                'misses': cache_misses,
                'total_hits': cache_hits + cache_misses,
                'total_misses': cache_misses,
                'hit_ratio': cache_hits / (cache_hits + cache_misses) if cache_hits + cache_misses > 0 else 0
            }

        return memoize, cache_stats

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        item = dict.popitem(self)
        return (item[0], item[1])
    except KeyError, e:
        raise BadRequestKeyError(str(e))

