def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ArgumentError("Inventory must be a dictionary", "inventory")

    if extract_spec_version:
        if 'type' not in inventory:
            raise ArgumentError("Inventory must have a 'type' key", "inventory")
        if not isinstance(inventory['type'], str):
            raise ArgumentError("Inventory 'type' must be a string", "inventory['type']")

        spec_version = inventory['type']
    else:
        spec_version = self.spec_version

    if spec_version not in self.specs:
        raise ArgumentError("Spec version not found in specs", "spec_version")

    spec = self.specs[spec_version]

    for key, value in inventory.items():
        if key not in spec:
            raise ArgumentError(f"Inventory key '{key}' not found in spec", key)

        field_type = spec[key]

        if isinstance(field_type, Schema):
            # Nested documents cannot have validation
            if not set(field_type.keys()).issubset(set(['type', 'required', 'nullable', 'default'])):
                raise SchemaFormatException("Unsupported field spec item at {}. Items: "+repr(field_type.keys()), key)
            self._verify_type(value, key)

        elif isinstance(field_type, Array):
            if not isinstance(field_type.contained_type, (type, Schema, Array, types.FunctionType)):
                raise SchemaFormatException("Unsupported field type contained by Array at {}.", key)

        elif not isinstance(field_type, type) and not isinstance(field_type, types.FunctionType):
            raise SchemaFormatException("Unsupported field type at {}. Type must be a type, a function, an Array or another Schema", key)

        self._validate_type(value, key)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of manifest files to check
    :param digests_used: List of digests that are needed to be present and used
    """
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            manifest_content = file.read()
            for line in manifest_content.split('\n'):
                if line.startswith('digest:'):
                    digest = line.split(':')[1].strip()
                    if digest not in digests_used:
                        print(f"Digest {digest} is not used in the manifest.")
                    else:
                        print(f"Digest {digest} is used in the manifest.")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError('Input prior must be an InventoryValidator object')

    if not self.is_valid_inventory():
        raise ValueError('Current inventory is not valid')

    if not prior.is_valid_inventory():
        raise ValueError('Prior inventory is not valid')

    if not self.is_valid_prior_version(prior):
        raise ValueError('Prior version is not valid')

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    if not manifest_files:
        raise ValueError("Manifest files cannot be empty")

    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File {file} is not listed in the manifest")

