def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Check if the storage root hierarchy is valid
    if self._storage_root_hierarchy is not None:
        num_objects += 1
        if validate_objects:
            # Validate each object in the hierarchy
            for obj in self._storage_root_hierarchy:
                if obj.is_valid():
                    good_objects += 1
                else:
                    if show_warnings:
                        print(f"Invalid object: {obj}")
        if check_digests:
            # Check the digests of the objects in the hierarchy
            for obj in self._storage_root_hierarchy:
                if obj.check_digest():
                    good_objects += 1
                else:
                    if show_warnings:
                        print(f"Invalid digest for object: {obj}")
    else:
        if show_warnings:
            print("No storage root hierarchy found.")

    return num_objects, good_objects

