def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    result = ""
    while number > 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

import re

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_keys = {}
    for key, value in item.items():
        if key.endswith('.cpp'):
            regex_keys[key] = re.compile(key.replace('.', '\\.'))
        else:
            regex_keys[key] = value
    return regex_keys

def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1]
        if name.startswith('<') and name.endswith('>'):
            return name[1:-1]
    return name

import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name == 'posix' if os.name else 1
    elif platform == 0:
        platform = 0
    elif platform == 1:
        platform = 1
    else:
        raise ValueError("Invalid platform value")

    if platform == 0:
        return shlex.split(s)
    else:
        return re.split(r'[\s,]+', s)

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None
    match = re.match(r'(\d+)\s*([a-zA-Z]+)', frequency)
    if not match:
        raise ValueError("Invalid frequency format")
    number = int(match.group(1))
    unit = match.group(2)
    if unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError("Unsupported unit of time")

