def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check if explicit __metaclass__ is provided
    if explicit_mc is not None:
        return explicit_mc

    # Initialize metaclass to None
    metaclass = None

    # Iterate through bases to find explicit metaclass
    for base in bases:
        if hasattr(base, '__metaclass__'):
            metaclass = base.__metaclass__
            break

    # If no explicit metaclass is found, use the first base's metaclass
    if metaclass is None:
        metaclass = bases[0].__class__

    return metaclass

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                    self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

