    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    _PATH_RE = re.compile(r'(?P<url>https?://[^ ]+)|(?P<path>[^ ]+)')
    memoized_urls = {}

    return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

import urllib.request

from urllib.parse import urlparse

from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
        if not scheme in ('http', 'https', 'ftp', 'ftps'):
            return None
        req = urllib.request.HeadRequest(url, headers={'Host': netloc})
        resp = urllib.request.urlopen(req)
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', '')
    except Exception as e:
        print(f"Error fetching content type: {e}")
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is not empty
    if not tag:
        return False

    # Check if the tag contains only alphanumeric characters
    if not tag.isalnum():
        return False

    # Check if the tag is not too long
    if len(tag) > 50:
        return False

    # Check if the tag is not too short
    if len(tag) < 2:
        return False

    # Check if the tag is not a reserved word
    if tag.lower() in ['owner', 'gdpr', 'admin']:
        return False

    # If all checks pass, the tag is valid
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        children_dict[child.tag] = child.text
    return children_dict

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url.startswith("http://") and not url.startswith("https://"):
        raise ValueError("Invalid URL format. URL must start with 'http://' or 'https://'")
    if document_path and not document_path.startswith("/"):
        document_path = "/" + document_path
    document = {
        "version": "1.0",
        "server": {
            "baseUrl": url,
            "name": "NodeInfo Server",
            "software": "NodeInfo Server",
            "version": "1.0",
        },
        "protocols": ["diaspora"],
        "relay": "",
        "services": {
            "inbound": [],
            "outbound": [],
        },
        "openRegistrations": True,
        "usage": {
            "users": {
                "total": 0,
                "activeHalfyear": 0,
                "activeMonth": 0,
                "activeWeek": 0,
            },
            "localPosts": 0,
            "localComments": 0,
        }
    }
    if document_path:
        document["document_path"] = document_path
    return document

