def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        include_dict = parser_dict['include']
        for key, value in iteritems(include_dict):
            if isinstance(value, dict):
                self._include_groups(value)
            else:
                parser_dict[key] = value

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = self.spec.get()
    other_defaults = self._get_other_defaults()
    return {**spec_defaults, **other_defaults}

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
    }
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_arg_mapping = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }
    for old, new in deprecated_arg_mapping.items():
        if old in cli_args:
            warnings.warn(
                "Deprecated argument '{0}' has been deprecated in favour "
                "of '{1}'. '{0}' will be removed in a future version."
                .format(old, new),
                category=DeprecationWarning,
                stacklevel=2,
            )
            cli_args[new] = cli_args.pop(old)
    for old, new in deprecated_arg_mapping.items():
        if old in answer_file_args:
            warnings.warn(
                "Deprecated argument '{0}' has been deprecated in favour "
                "of '{1}'. '{0}' will be removed in a future version."
                .format(old, new),
                category=DeprecationWarning,
                stacklevel=2,
            )
            answer_file_args[new] = answer_file_args.pop(old)

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    if not args:
        raise ValueError("No arguments provided.")
    for arg in self.required_args:
        if arg not in args:
            raise ValueError(f"Missing required argument: {arg}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument '{arg}' is longer than the specified length.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    choices = self.choices  # Assuming self.choices is a list of available choices
    for arg in args:
        if arg not in choices:
            raise ValueError(f"Invalid choice: {arg}. Available choices are: {choices}")

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg[9:]] = arg[9:]
        elif arg.startswith('--nested-'):
            nested_args[arg[9:]] = arg[9:]

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    for extra_var in extra_vars:
        if extra_var not in vars_dict:
            vars_dict[extra_var] = extra_var
        else:
            vars_dict[extra_var] = vars_dict[extra_var] + extra_var

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    plugin_data = json.load(f)
                    for key, value in plugin_data.items():
                        plugin_spec[key] = value
    return plugin_spec
